loveCount\":27,\"params\":{\"nickName\":\"JCXYOZH\",\"avatar\":\"/profile/avatar/2025/04/05/blob_20250405145233A009.jpeg\",\"userName\":\"lzh\",\"userId\":1887171475342868481,\"categoryName\":\"出售\",\"categoryId\":1644303516352962562},\"status\":1,\"tags\":[],\"type\":1,\"userId\":1887171475342868481},{\"categoryId\":1602336520042287105,\"content\":\"信息墙主要提供表白交友、提问求助、吐槽提醒、遗失物招领、闲置物交易、兼职招聘等校园信息， 运营方联合校园相关部门人员管理，用户不得散播影响本校声誉等的不实谣言，违者将按校规严肃处理。\",\"contentId\":1908414450014052354,\"createTime\":\"2025-04-05 15:00:36\",\"fileCount\":3,\"isAnonymous\":0,\"loveCount\":23,\"params\":{\"nickName\":\"JCXYOZH\",\"avatar\":\"/profile/avatar/2025/04/05/blob_20250405145233A009.jpeg\",\"userName\":\"lzh\",\"userId\":1887171475342868481,\"categoryName\":\"日常分享\",\"categoryId\":16023365200422871',0,NULL,'2025-04-05 16:46:26'),(1908441099350794242,'campus','API接口日志记录','查询信息墙详细内容','com.oddfar.campus.business.controller.web.ContentInfoController.getContentById()','GET',NULL,'/campus/getContent','127.0.0.1','{}','{\"msg\":\"success\",\"code\":200,\"data\":{\"categoryId\":1602336520042287105,\"content\":\"哪个好心人捡到充电宝啊？\",\"contentId\":1908397825089036290,\"createTime\":\"2025-04-05 13:54:32\",\"fileCount\":9,\"fileUrl\":[\"/profile/CampusFile/2025/04/05/mmexport1743831506040_20250405135423A002.jpg\"],\"isAnonymous\":0,\"loveCount\":0,\"params\":{\"nickName\":\"墙墙管理员\",\"avatar\":\"/profile/avatar/2025/04/05/blob_20250405144601A008.jpeg\",\"userName\":\"wallManage\",\"userId\":2,\"categoryName\":\"日常分享\",\"categoryId\":1602336520042287105},\"status\":1,\"tags\":[],\"type\":1,\"userId\":2},\"isLove\":false}',0,NULL,'2025-04-05 16:46:30'),(1908441104899858434,'lzh','API接口日志记录','获取用户信息','com.oddfar.campus.admin.controller.system.SysLoginController.getInfo()','GET',1,'/getInfo','127.0.0.1','{}','{\"msg\":\"success\",\"code\":200,\"permissions\":[\"*:*:*\"],\"roles\":[\"admin\"],\"user\":{\"admin\":true,\"avatar\":\"/profile/avatar/2025/04/05/blob_20250405145416A010.jpeg\",\"createTime\":\"2024